code:
Адрес = ЭтотОбъект.АдресGitAPI;
Репо = ЭтотОбъект.РепозиторийGit;
Ветка = ЭтотОбъект.ВеткаGit;
Токен = ЭтотОбъект.ТокенGit;
Корень = ЭтотОбъект.КаталогБазыЗнанийGit;

Схема = "";
Хост = "";
Порт = 0;
БазовыйПуть = "";
ОшибкаИнициализации = "";

Если НРег(Лев(Адрес, 8)) = "https://" Тогда
	Схема = "https";
	Ост = Сред(Адрес, 9);
ИначеЕсли НРег(Лев(Адрес, 7)) = "http://" Тогда
	Схема = "http";
	Ост = Сред(Адрес, 8);
Иначе
	ОшибкаИнициализации = "Неизвестная схема URL: " + Адрес;
КонецЕсли;

Если НЕ ЗначениеЗаполнено(ОшибкаИнициализации) Тогда
	ПозСлэш = СтрНайти(Ост, "/");
	Если ПозСлэш = 0 Тогда
		ХостПорт = Ост;
		БазовыйПуть = "/";
	Иначе
		ХостПорт = Лев(Ост, ПозСлэш - 1);
		БазовыйПуть = Сред(Ост, ПозСлэш);
	КонецЕсли;

	ПозДвоеточ = СтрНайти(ХостПорт, ":");
	Если ПозДвоеточ > 0 Тогда
		Хост = Лев(ХостПорт, ПозДвоеточ - 1);
		Порт = Число(Сред(ХостПорт, ПозДвоеточ + 1));
	Иначе
		Хост = ХостПорт;
		Порт = ?(Схема = "https", 443, 80);
	КонецЕсли;

	Защищ = ?(Схема = "https", Новый ЗащищенноеСоединениеOpenSSL(), Неопределено);
	Соединение = Новый HTTPСоединение(Хост, Порт, , , , 30, Защищ);

	Заголовки = Новый Соответствие;
	Заголовки.Вставить("Authorization", "Bearer " + Токен);
	Заголовки.Вставить("Accept", "application/vnd.github+json");

	Очередь = Новый Массив;
	Очередь.Добавить(Корень);

	КолФайлов = 0;
	ОбщийРазмер = 0;
	Расширения = Новый Соответствие;
	Ошибки = Новый Массив;
	Индекс = 0;

	Пока Индекс < Очередь.Количество() Цикл
		ТекПапка = Очередь[Индекс];
		Индекс = Индекс + 1;

		АдресРесурса = БазовыйПуть + "repos/" + Репо + "/contents/" + ТекПапка + "?ref=" + Ветка;
		Страница = 1;

		Пока Истина Цикл
			АдресСтр = АдресРесурса + "&page=" + Формат(Страница, "ЧГ=0") + "&per_page=100";
			Запрос = Новый HTTPЗапрос(АдресСтр, Заголовки);
			Ответ = Соединение.Получить(Запрос);

			Если Ответ.КодСостояния <> 200 Тогда
				Ошибки.Добавить(СтрШаблон("%1 — HTTP %2", ТекПапка, Ответ.КодСостояния));
				Прервать;
			КонецЕсли;

			Чтение = Новый ЧтениеJSON;
			Чтение.УстановитьСтроку(Ответ.ПолучитьТелоКакСтроку());
			Элементы = ПрочитатьJSON(Чтение);
			Чтение.Закрыть();

			Если Элементы.Количество() = 0 Тогда
				Прервать;
			КонецЕсли;

			Для Каждого Эл Из Элементы Цикл
				Если Эл.type = "dir" Тогда
					Очередь.Добавить(Эл.path);
				ИначеЕсли Эл.type = "file" Тогда
					КолФайлов = КолФайлов + 1;
					ОбщийРазмер = ОбщийРазмер + Эл.size;
					Тчк = СтрНайти(Эл.name, ".", НаправлениеПоиска.СКонца);
					Расш = ?(Тчк > 0, НРег(Сред(Эл.name, Тчк + 1)), "без расширения");
					Тек = Расширения.Получить(Расш);
					Расширения.Вставить(Расш, ?(Тек = Неопределено, 1, Тек + 1));
				КонецЕсли;
			КонецЦикла;

			Страница = Страница + 1;
		КонецЦикла;
	КонецЦикла;

	Результат = СтрШаблон("Каталог: %1 | Папок: %2 | Файлов: %3 | Объём: %4 КБ (%5 МБ)",
		Корень, Индекс, КолФайлов, Окр(ОбщийРазмер / 1024, 1), Окр(ОбщийРазмер / 1048576, 2));

	Если Расширения.Количество() > 0 Тогда
		Результат = Результат + Символы.ПС + "По типам:";
		Для Каждого Кз Из Расширения Цикл
			Результат = Результат + Символы.ПС + СтрШаблон("  .%1 — %2 шт", Кз.Ключ, Кз.Значение);
		КонецЦикла;
	КонецЕсли;

	Если Ошибки.Количество() > 0 Тогда
		Результат = Результат + Символы.ПС + "Ошибки: " + СтрСоединить(Ошибки, "; ");
	КонецЕсли;
Иначе
	Результат = ОшибкаИнициализации;
КонецЕсли;
